    el.querySelector('#buildQuickWorkout').onclick=()=>{const minutes=+$('#quickDuration').value,goal=$('#quickGoal').value,skill=$('#quickLevel').value,equipment=$('#quickEquipment').value,roundTime=skill==='basic'?120:180,restTime=skill==='advanced'?45:30,warmupTime=45,rounds=Math.max(2,Math.round((minutes*60-warmupTime+restTime)/(roundTime+restTime))),focusMap={technique:['jabs','short','movement'],cardio:['speed','high','explosive'],power:['power','body'],defense:['defense','footwork'],mixed:['jabs','body','defense','mixed']},includeMap={technique:['punch','defense','footwork'],cardio:['punch','footwork'],power:['punch','body'],defense:['punch','defense','footwork'],mixed:['punch','body','defense','footwork']};apply({skill,trainingMode:equipment==='shadow'?'shadow':'bag',complexity:skill==='basic'?'low':skill==='advanced'?'high':'medium',focusEnabled:'yes',focuses:focusMap[goal],includeTypes:includeMap[goal],punchOuts:goal==='cardio',workout:{rounds,warmupTime,roundTime,restTime,pace:goal==='cardio'?4:6}})};
