  function programConfig(focus,index){const advanced=index>3;return {skill:advanced?'intermediate':'basic',complexity:advanced?'medium':'low',focusEnabled:'yes',focuses:[focus],coachCues:true,guidedBeginner:!advanced,punchOuts:['high','explosive'].includes(focus),includeTypes:focus==='body'?['punch','body']:focus==='defense'?['punch','defense','footwork']:focus==='inside'?['punch','body','knee']:['punch','body','defense','footwork'],workout:{rounds:advanced?6:4,warmupTime:45,roundTime:advanced?180:120,restTime:30,pace:advanced?5:7}}}
  function buildPrograms(){const progress=read('cornerwork-program-progress',{}),content='<p class="feature-note">Structured plans remember your next session on this device.</p><div class="program-grid">'+programs.map(p=>{const done=Math.min(progress[p.id]||0,p.sessions.length),next=p.sessions[Math.min(done,p.sessions.length-1)];return '<button class="program-card" data-program="'+p.id+'"><strong>'+p.name+'</strong><span>'+p.detail+'</span><span>'+(done===p.sessions.length?'Complete':'Next: '+next[0])+' · '+done+'/'+p.sessions.length+'</span><div class="program-progress"><i style="width:'+Math.round(done/p.sessions.length*100)+'%"></i></div></button>'}).join('')+'</div>';const el=modal('programDialog','Training Programs',content);el.querySelectorAll('[data-program]').forEach(button=>button.onclick=()=>{const p=programs.find(x=>x.id===button.dataset.program),done=Math.min(progress[p.id]||0,p.sessions.length-1),session=p.sessions[done];sessionStorage.setItem('cornerwork-active-program',JSON.stringify({id:p.id,index:done,name:p.name,session:session[0]}));apply(programConfig(session[1],done))});return el}
  function buildTools(){const el=modal('toolsDialog','Training Tools','<p class="feature-note">Start a specialized session, study technique, use the camera mirror, or manage your Cornerwork data.</p><div class="mode-grid">'+modes.map((m,i)=>'<button class="mode-card" data-mode="'+i+'"><strong>'+m[0]+'</strong><span>'+m[1]+'</span></button>').join('')+'</div><div class="feature-actions"><button class="feature-secondary" id="openTechniques">Technique catalogue</button><button class="feature-secondary" id="openMirror">Mirror and record</button><button class="feature-secondary" id="openBackup">Backup and restore</button><button class="feature-secondary" id="installApp">Install app</button></div>');el.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>apply(modes[+b.dataset.mode][3]));return el}
