  function renderHistory(el=$('#historyDialog')){if(!el)return;const history=read('cornerwork-history',[]),s=historyStats(history),month=history.filter(x=>Date.now()-x.date<2592000000).length,week=history.filter(x=>Date.now()-x.date<604800000).length;el.querySelector('#historyContent').innerHTML='<div class="stats-grid"><div class="stat-card"><strong>'+history.length+'</strong><span>Workouts</span></div><div class="stat-card"><strong>'+s.rounds+'</strong><span>Rounds</span></div><div class="stat-card"><strong>'+fmt(s.total)+'</strong><span>Training</span></div><div class="stat-card"><strong>'+s.streak+'</strong><span>Day streak</span></div></div><p class="feature-note">'+week+' this week · '+month+' this month · '+s.moves+' total moves</p><div class="history-list">'+(history.length?history.slice(0,50).map(x=>'<div class="history-item"><div><strong>'+new Date(x.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})+'</strong><span>'+safe(x.skill)+' '+safe(x.mode)+' · '+x.rounds+' rounds · '+fmt(x.duration||x.plannedDuration)+'</span></div><b>'+x.combos+' combos</b></div>').join(''):'<p class="feature-note">Your completed workouts will appear here.</p>')+'</div>'}
