  function buildBackup(){const el=modal('backupDialog','Backup and Restore','<p class="feature-note">Export all local settings, workouts, custom combos, and history. The file can restore Cornerwork in another browser.</p><div class="backup-grid"><button class="feature-primary" id="exportCornerwork">Export backup</button><label class="feature-secondary" style="text-align:center;cursor:pointer">Import backup<input id="importCornerwork" type="file" accept="application/json" hidden></label></div><button class="feature-primary install-button" id="installCornerwork">Install Cornerwork</button>');el.querySelector('#exportCornerwork').onclick=()=>{const blob=new Blob([JSON.stringify(api.exportData(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cornerwork-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};el.querySelector('#importCornerwork').onchange=async e=>{try{api.importData(JSON.parse(await e.target.files[0].text()))}catch(err){alert('That backup file could not be read.')}};return el}
